class ObserverGraph {
public:
    /**
     * @brief Get the singleton instance of the graph.
     * @return ObserverGraph& singleton reference.
     */
    [[nodiscard]] static ObserverGraph &getInstance() noexcept {
        static ObserverGraph instance;
        return instance;
