    bool isNodeInActiveBatch(const NodePtr &node) const {
        ConditionalSharedLock<ConditionalSharedMutex> lock(m_graphMutex);
        auto it = m_activeBatchNodes.find(node);
        return it != m_activeBatchNodes.end() && !it->second.empty();
    }

