    std::function<void()> saveNodeStateForRollback(const NodePtr &node) {
        if (!node) return []() {};

        ConditionalSharedLock<ConditionalSharedMutex> readLock(m_graphMutex);
        // Save current state
        NodeSet originalDependents;
        if (m_dependentList.contains(node)) {
