    void addWeakRef() noexcept {
        m_weakRefCount++;
    }

    /// @brief Decreases weak reference count and invalidates if reaching zero.
    void releaseWeakRef() noexcept {
        if (--m_weakRefCount == 0) {
            this->handleInvalid(*this);
