        case ErrorCode::MEMORY_ALLOCATION_FAILURE:
            return "MEMORY_ALLOCATION_FAILURE";
        case ErrorCode::GRAPH_CORRUPTION:
            return "GRAPH_CORRUPTION";
        case ErrorCode::OBSERVER_LIMIT_EXCEEDED:
            return "OBSERVER_LIMIT_EXCEEDED";
        default:
            return "UNKNOWN";
        }
    }

