                is_sbo_storage = true;
                is_initialized = true;
            } else {
                // Use heap allocation
                new(&storage.heap_ptr) std::unique_ptr<Type>(std::make_unique<Type>(std::forward<T>(t)));
                is_sbo_storage = false;
                is_initialized = true;
            }
        } else {
