    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && LeftShiftAssignable<Type, U>)
    React &operator<<=(const U &rhs) {
        atomicLeftShiftAssign(*getPtr(), rhs);
        return *this;
