    Expression(T &&expr) : m_expr(std::forward<T>(expr)) {
    }

protected:
    /// @brief Sets the operator expression as the current source.
    void setOpExpr() {
        this->setSource([this]() {
            return m_expr();
        });
    }

private:
    BinaryOpExpr<Op, L, R> m_expr;
};

